import{_ as o,o as d,c,a5 as a}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"注解","description":"","frontmatter":{"title":"注解","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","附录","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/附录/未分类/一发入魂/注解.md","filePath":"posts/java快速入门/附录/未分类/一发入魂/注解.md"}'),t={name:"posts/java快速入门/附录/未分类/一发入魂/注解.md"};function p(s,e,l,r,i,n){return d(),c("div",null,[...e[0]||(e[0]=[a("<div><p><code>mp</code>一共提供了<code>8</code>个注解，这些注解是用在<code>Java</code>的实体类上面的。 <code>@TableName</code> 注解在类上，指定类和数据库表的映射关系。实体类的类名（转成小写后）和数据库表名相同时，可以不指定该注解。</p><p><code>@TableId</code> 注解在实体类的某一字段上，表示这个字段对应数据库表的主键。当主键名为<code>id</code>时（表中列名为<code>id</code>，实体类中字段名为<code>id</code>），无需使用该注解显式指定主键，<code>mp</code>会自动关联。若类的字段名和表的列名不一致，可用<code>value</code>属性指定表的列名。另，这个注解有个重要的属性<code>type</code>，用于指定主键策略，参见主键策略小节</p><p><code>@TableField</code> 注解在某一字段上，指定<code>Java</code>实体类的字段和数据库表的列的映射关系。这个注解有如下几个应用场景。</p><ul><li>排除非表字段</li></ul><p>若<code>Java</code>实体类中某个字段，不对应表中的任何列，它只是用于保存一些额外的，或组装后的数据，则可以设置<code>exist</code>属性为<code>false</code>，这样在对实体对象进行插入时，会忽略这个字段。排除非表字段也可以通过其他方式完成，如使用<code>static</code>或<code>transient</code>关键字，但个人觉得不是很合理，不做赘述</p><ul><li>字段验证策略</li></ul><p>通过<code>insertStrategy</code>，<code>updateStrategy</code>，<code>whereStrategy</code>属性进行配置，可以控制在实体对象进行插入，更新，或作为<code>WHERE</code>条件时，对象中的字段要如何组装到<code>SQL</code>语句中。参见配置小节 • 字段填充策略 通过<code>fill</code>属性指定，字段为空时会进行自动填充</p><p><code>@Version</code> 乐观锁注解，参见乐观锁小节</p><p><code>@EnumValue</code> 注解在枚举字段上</p><p><code>@TableLogic</code> 逻辑删除，参见逻辑删除小节 <code>KeySequence</code> 序列主键策略（<code>oracle</code>） • <code>InterceptorIgnore</code> 插件过滤规则</p></div>",1)])])}const m=o(t,[["render",p]]);export{u as __pageData,m as default};
